private SaveData? enemyState86;private string enemyMap86="";
private void RememberEnemies86(){if(!ReferenceEquals(enemyState86,game.State)||enemyMap86.Length==0)return;foreach(var e in enemyPositions){string k=enemyMap86+":"+e.Key;if(!game.State.DefeatedEnemies.Contains(k))game.State.EnemyLocations86[k]=new(e.Value.X,e.Value.Y,enemyFacing.GetValueOrDefault(e.Key));}}
private Vector2I? NearbyFree86(Vector2I p,bool heroSpawn){for(int radius=0;radius<12;radius++)for(int dx=-radius;dx<=radius;dx++)for(int dy=-radius;dy<=radius;dy++){if(Math.Abs(dx)+Math.Abs(dy)!=radius)continue;var q=p+new Vector2I(dx,dy);if(!Blocked(game.State.Map,q.X,q.Y)&&!enemyPositions.Values.Contains(q)&&!NpcBlocksEnemy(q))return q;}return null;}
private void Check86(){int n=0;void C(bool ok,string label){if(!ok)throw new Exception(label);n++;}game.StartNew(HeroId.Gladia,Difficulty.Sopravvivenza);ResetEventRules();screen=Screen.World;EnterMap("casa_olmo",14,16);game.State.StoryFlags.Add("pentesilea_met");string id="olmo_undead_3";var at=new Vector2I(22,6);C(!Blocked("casa_olmo",at.X,at.Y),"target free");enemyPositions[id]=at;enemyFacing[id]=2;EnterMap("strada",8,22);C(game.State.EnemyLocations86["casa_olmo:"+id].X==22,"stored map");EnterMap("casa_olmo",14,16);C(enemyPositions[id]==at&&enemyFacing[id]==2,"return exact");RememberEnemies86();game=GameRules.FromJson(game.ToJson());ResetEventRules();EnterMap("casa_olmo",14,16);C(enemyPositions[id]==at,"load exact");game.State.DefeatedEnemies.Add("casa_olmo:"+id);RebuildEnemies();C(!enemyPositions.ContainsKey(id),"dead stays dead");game.StartNew(HeroId.Gladia,Difficulty.Sopravvivenza);ResetEventRules();EnterMap("casa_olmo",14,16);C(enemyPositions[id]==new Vector2I(23,5),"new game resets");C(game.State.EnemyLocations86.Count==0,"no leak");foreach(var p in CurrentMap().Props.Where(p=>p.Id.StartsWith("floor86_"))){C(Blocked("casa_olmo",(int)p.X,(int)p.Y),"hole blocked");C(p.PaintOnly,"baked hole");}var seen=new HashSet<Vector2I>{new(14,16)};var q=new Queue<Vector2I>(seen);while(q.Count>0){var p=q.Dequeue();foreach(var d in NeighborSteps){var v=p+d;if(!Blocked("casa_olmo",v.X,v.Y)&&seen.Add(v))q.Enqueue(v);}}foreach(var p in new[]{new Vector2I(10,4),new Vector2I(6,12),new Vector2I(10,16),new Vector2I(14,21),new Vector2I(14,2)})C(seen.Contains(p),"route "+p);GD.Print($"PERSIST86_OK {n}");GetTree().Quit();}}
